const body = $input.first().json.body || $input.first().json;
const esc = (v) => v == null ? null : String(v).replace(/'/g, "''");
const num = (v) => v == null || v === '' ? 0 : Number(v);
const fields = [
  'lead_id', 'operador_id', 'nombre_comercial', 'nombre_contacto', 'fecha',
  'nombre_facturacion', 'nombre_empresa', 'dni_cif', 'direccion', 'ciudad',
  'provincia', 'codigo_postal', 'telefono', 'email', 'pagina_web', 'categorias',
  'precio_sin_iva', 'precio_con_iva', 'notas'
];
const numericFields = ['lead_id', 'operador_id', 'precio_sin_iva', 'precio_con_iva'];
const cols = fields.join(', ');
const vals = fields.map(f => {
  if (numericFields.includes(f)) return num(body[f]);
  const v = esc(body[f]);
  return v == null ? 'NULL' : `'${v}'`;
}).join(', ');
const query = `INSERT INTO crm_bybusiness.hojas_venta (${cols}) VALUES (${vals}) RETURNING id`;
return [{ json: { query, hoja_id_expected: true } }];

const result = $input.first().json;
const hojaId = result.id || (Array.isArray(result) && result[0]?.id);
return [{ json: { ok: true, hoja_id: hojaId } }];
